from __future__ import annotations
import math
import numpy as np
import numpy as np
from scipy.optimize import least_squares
from . import track_wormhole_skill

__all__ = ['cauchy_linear_fit', 'fit_anchored_relaxation', 'fit_local_level_step']

def _real(value: object) -> np.ndarray:
    array = np.asarray(value)
    if array.dtype.kind not in 'iuf':
        raise ValueError('Expected real numeric input.')
    array = array.astype(np.float64, copy=False)
    if not np.all(np.isfinite(array)):
        raise ValueError('Expected finite float64 input.')
    return array


def _scalar(value: float) -> float:
    array = _real(value)
    if array.ndim != 0:
        raise ValueError('Expected a scalar.')
    return float(array)


def _mad(residual: np.ndarray) -> float:
    return float(1.4826 * np.median(np.abs(residual - np.median(residual))))


@track_wormhole_skill("autogenous_prim_robust_trend_decomposition")
def cauchy_linear_fit(design: np.ndarray, values: np.ndarray, *, scale: float | None=None, noise_floor: float=1e-08) -> tuple[np.ndarray, float]:
    """Fit finite design (n,p) and values (n,) with n >= p >= 1, full column rank before and after weighting, and positive scale if supplied and positive floor, returning (coefficients (p,), floored residual MAD)."""
    (a, y) = (_real(design), _real(values))
    noise_floor = _scalar(noise_floor)
    if scale is not None:
        scale = _scalar(scale)
    if a.ndim != 2 or not 1 <= a.shape[1] <= a.shape[0] or y.shape != (a.shape[0],):
        raise ValueError('Expected design (n,p) and values (n,), with n >= p >= 1.')
    if noise_floor <= 0 or (scale is not None and scale <= 0):
        raise ValueError('Scale and noise floor must be positive.')
    (beta, _, rank, _) = np.linalg.lstsq(a, y, rcond=None)
    if rank != a.shape[1]:
        raise ValueError('Design must have full column rank.')
    if scale is None:
        scale = max(noise_floor, _mad(y - a @ beta))
    for _ in range(12):
        root_weight = scale / np.hypot(scale, y - a @ beta)
        (beta, _, rank, _) = np.linalg.lstsq(a * root_weight[:, None], y * root_weight, rcond=None)
        if rank != a.shape[1]:
            raise ValueError('Weighted design must have full column rank.')
    return (beta, max(noise_floor, _mad(y - a @ beta)))


@track_wormhole_skill("autogenous_prim_robust_trend_decomposition")
def fit_anchored_relaxation(time: np.ndarray, predictor: np.ndarray, values: np.ndarray, *, onset_rate: float, noise_scale: float, curvature_ratio: float, bins: int, tau_bounds: tuple[float, float]) -> tuple[float, float, float | None]:
    """Fit finite vectors time, predictor, and values (n,) with n >= 4, increasing nonnegative times, a predictor independent of the intercept, nonnegative rate and curvature ratio, positive noise scale, 2 <= bins <= n, and ordered positive tau bounds, returning (offset, positive slope, tau or None for constant rate) with a locally identifiable saturation fit when used."""
    (t, x, y) = (_real(time), _real(predictor), _real(values))
    (onset_rate, noise_scale, curvature_ratio) = map(_scalar, (onset_rate, noise_scale, curvature_ratio))
    bounds = _real(tau_bounds)
    if t.ndim != 1 or t.size < 4 or x.shape != t.shape or (y.shape != t.shape):
        raise ValueError('Expected aligned vectors with at least four samples.')
    if t[0] < 0 or np.any(t[1:] <= t[:-1]):
        raise ValueError('Times must increase from a nonnegative elapsed time.')
    if onset_rate < 0 or noise_scale <= 0 or curvature_ratio < 0:
        raise ValueError('Expected nonnegative rate and curvature ratio and positive noise scale.')
    if not isinstance(bins, (int, np.integer)) or not 2 <= bins <= t.size:
        raise ValueError('Expected between two and n bins.')
    if bounds.shape != (2,) or not 0 < bounds[0] < bounds[1]:
        raise ValueError('Expected ordered, distinct, positive tau bounds.')
    a = np.column_stack((np.ones_like(x), x))
    corrected = y - onset_rate * t
    (beta, _) = cauchy_linear_fit(a, corrected, scale=noise_scale)
    medians = np.array([np.median(part) for part in np.array_split(corrected - a @ beta, bins)])
    coherent = np.sqrt(np.mean(medians ** 2))
    if beta[1] > 0 and coherent <= curvature_ratio * noise_scale:
        return (float(beta[0]), float(beta[1]), None)
    if onset_rate == 0:
        raise ValueError('Saturation cannot resolve a failed constant-rate fit with zero onset rate.')
    (lo, hi) = np.log(bounds)
    start = (lo + hi) / 2

    def relaxation(log_tau: float) -> np.ndarray:
        tau = np.exp(log_tau)
        return onset_rate * (tau * -np.expm1(-t / tau))

    def residual(params: np.ndarray) -> np.ndarray:
        return a @ params[:2] + relaxation(params[2]) - y
    (seed, _) = cauchy_linear_fit(a, y - relaxation(start), scale=noise_scale)
    fit = least_squares(residual, [seed[0], max(0.0, seed[1]), start], bounds=([-np.inf, 0.0, lo], [np.inf, np.inf, hi]), loss='soft_l1', f_scale=noise_scale, x_scale='jac')
    if not fit.success:
        raise RuntimeError('Anchored relaxation fit did not converge.')
    if fit.active_mask[1] != 0 or np.linalg.matrix_rank(fit.jac) < 3:
        raise ValueError('Saturation fit needs a positive interior slope and full-rank Jacobian.')
    return (float(fit.x[0]), float(fit.x[1]), float(np.exp(fit.x[2])))


@track_wormhole_skill("autogenous_prim_robust_trend_decomposition")
def fit_local_level_step(predictor: np.ndarray, values: np.ndarray, splits: np.ndarray, *, scale: float, loss_clip: float) -> tuple[int, float]:
    """Fit finite predictor and values (n,) and integer splits (k,) with k >= 1, at least three samples per side, full-rank split designs, and positive scale and loss clip, returning (best split index, signed level change)."""
    (x, y) = (_real(predictor), _real(values))
    splits = np.asarray(splits)
    (scale, loss_clip) = (_scalar(scale), _scalar(loss_clip))
    if x.ndim != 1 or y.shape != x.shape or x.size < 6:
        raise ValueError('Expected aligned vectors with at least six samples.')
    if splits.ndim != 1 or not splits.size or splits.dtype.kind not in 'iu':
        raise ValueError('Expected a nonempty vector of integer splits.')
    if np.any(splits < 3) or np.any(splits > x.size - 3):
        raise ValueError('Each split must leave at least three samples per side.')
    if scale <= 0 or loss_clip <= 0:
        raise ValueError('Scale and loss clip must be positive.')
    indices = np.arange(x.size)
    a = np.column_stack((np.ones_like(x), x - np.median(x), np.zeros_like(x)))
    best_loss = np.inf
    (best_split, best_step) = (int(splits[0]), 0.0)
    for j in splits:
        a[:, 2] = indices >= j
        (beta, _) = cauchy_linear_fit(a, y, scale=scale)
        loss = np.minimum(np.abs(y - a @ beta), loss_clip).mean()
        if loss < best_loss:
            best_loss = loss
            (best_split, best_step) = (int(j), float(beta[2]))
    return (best_split, best_step)

