    t = (float(min(box, np.sqrt(2 * l0) / np.sqrt(l2))) if lam2 else M) if lam0 else 0.0
    slope = lam0 / t + lam2 * t / 2 if t else 0.0

    def relax(zero: int, active: int, start: np.ndarray, threshold: float) -> tuple[float, np.ndarray]:
        free = np.flatnonzero((zero | active) & bits == 0)
        if not free.size:
            b = fit(active)
            return (witness(b, zero, active), b)
        lb = witness(start, zero, active)
        if lb >= threshold:
            return (lb, start)
        fixed = np.flatnonzero(active & bits != 0)
        (j, sign) = (fixed.tolist(), [1.0] * fixed.size)
        (lin, diag) = ([0.0] * fixed.size, [lam2] * fixed.size)
        (bounds, x0) = ([(-M, M)] * fixed.size, start[fixed].tolist())
        if not lam0:
            j.extend(free)
            sign.extend([1.0] * free.size)
            lin.extend([0.0] * free.size)
            diag.extend([lam2] * free.size)
            bounds.extend([(-M, M)] * free.size)
            x0.extend(start[free])
        else:
            for s in (1.0, -1.0):
                v = np.maximum(0.0, s * start[free])
                for (cap, cost, curvature, initial) in ((t, slope, 0.0, np.minimum(t, v)), (M - t, lam2 * t, lam2, np.maximum(0.0, v - t))):
                    if cap > 0:
                        j.extend(free)
                        sign.extend([s] * free.size)
                        lin.extend([cost] * free.size)
                        diag.extend([curvature] * free.size)
                        bounds.extend([(0.0, cap)] * free.size)
                        x0.extend(initial)
        j = np.asarray(j, dtype=int)
        sign = np.asarray(sign)
        H = G[np.ix_(j, j)] * sign[:, None] * sign
        H.flat[::len(j) + 1] += diag
        q = np.asarray(lin) - c[j] * sign

        def objective(v: np.ndarray) -> tuple[float, np.ndarray]:
            hv = H @ v
