            key = pending.pop()
            if key not in partition:
                continue
            (zero, active) = key
            fixed = zero | active
            while fixed:
                bit = fixed & -fixed
                fixed ^= bit
                sibling = (zero ^ bit, active ^ bit)
                if sibling not in partition:
                    continue
                parent = (zero & ~bit, active & ~bit)
